contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint amount) public {
        require(amount < 2**250);
        // Only view interactions are possible; the invariant must hold at any time.
        uint bal = address(c).balance;
        uint t1 = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        uint t2 = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        assert(address(c).balance == bal && bal % 10 ether == 0 && t1 == t2 && t1 <= block.timestamp);
    }
}

