pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 amount) internal {
        vm.assume(amount < 2**250);
        uint bal = address(c).balance;
        uint256 t1;
        try c.pastBlockTime() returns (uint256 __r) { t1 = __r; } catch { return; }
        uint256 t2;
        try c.pastBlockTime() returns (uint256 __r) { t2 = __r; } catch { return; }
        assertTrue(address(c).balance == bal && bal % 10 ether == 0 && t1 == t2 && t1 <= block.timestamp);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
